    "siteOnePage": "<!-- HERO SECTION -->\n    <section class=\"hero\">\n      <div class=\"container hero-grid\">\n        <div class=\"hero-content\">\n          <span class=\"hero-badge\" data-i18n=\"siteOnePagePage.badge\">PÁGINA ÚNICA & OBJETIVA</span>\n          <h1 class=\"hero-title\" data-i18n=\"siteOnePagePage.title\">Criação de Site One Page Profissional</h1>\n          <p class=\"hero-description\" data-i18n=\"siteOnePagePage.desc\">Apresente sua empresa, produtos e serviços em uma estrutura moderna de página única. Ideal para pequenos negócios e profissionais autônomos que buscam máxima agilidade e foco em conversão.</p>\n          <div class=\"hero-ctas\">\n            <a href=\"#\" class=\"btn btn-primary\" data-whatsapp-key=\"serviceOnePage\" data-track=\"whatsapp_click\" data-cta-position=\"onepage_hero\">\n              Quero meu site One Page\n              <svg class=\"btn-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n            </a>\n            <a href=\"/servicos/\" class=\"btn btn-secondary\">\n              Ver Todos os Serviços\n            </a>\n          </div>\n        </div>\n        <div class=\"hero-media\">\n          <img src=\"/assets/images/conexus-service-one-page-07.png.png\" alt=\"Criação de Site One Page CONEXUS\" width=\"580\" height=\"390\" loading=\"eager\" style=\"border-radius: var(--radius-lg); border: 1px solid var(--color-cyan-border); box-shadow: var(--shadow-subtle);\">\n        </div>\n      </div>\n    </section>\n\n    <!-- VANTAGENS DO SITE ONE PAGE -->\n    <section class=\"section section-dark\">\n      <div class=\"container\">\n        <div class=\"section-header\">\n          <span class=\"section-badge\" data-i18n=\"siteOnePagePage.whyBadge\">POR QUE ESCOLHER ONE PAGE</span>\n          <h2 class=\"section-title\" data-i18n=\"siteOnePagePage.whyTitle\">Comunicação clara, rápida e focada em resultados</h2>\n        </div>\n\n        <div class=\"grid grid-3\">\n          <div class=\"card\">\n            <div class=\"card-icon\" style=\"color: var(--color-cyan);\">\n              <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n            </div>\n            <h3 class=\"card-title\" data-i18n=\"siteOnePagePage.card1Title\">Leitura Fluida & Dinâmica</h3>\n            <p class=\"card-description\">\n              O visitante navega por todas as seções essenciais — sobre, serviços, diferenciais e contato — sem precisar trocar de página.\n            </p>\n          </div>\n\n          <div class=\"card\">\n            <div class=\"card-icon\" style=\"color: var(--color-cyan);\">\n              <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"2\" ry=\"2\"/><line x1=\"12\" y1=\"18\" x2=\"12.01\" y2=\"18\"/></svg>\n            </div>\n            <h3 class=\"card-title\" data-i18n=\"siteOnePagePage.card2Title\">Mobile First Perfeito</h3>\n            <p class=\"card-description\">\n              Interface pensada para uso em smartphones com carregamento rápido e botões de contato sempre ao alcance dos dedos.\n            </p>\n          </div>\n\n          <div class=\"card\">\n            <div class=\"card-icon\" style=\"color: var(--color-cyan);\">\n              <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"/></svg>\n            </div>\n            <h3 class=\"card-title\" data-i18n=\"siteOnePagePage.card3Title\">Foco Total em Conversão</h3>\n            <p class=\"card-description\">\n              Sem distrações. O fluxo de leitura conduz o visitante naturalmente para a chamada de ação no WhatsApp ou e-mail.\n            </p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- CTA BANNER -->\n    <section class=\"section section-cta\">\n      <div class=\"container text-center\">\n        <h2 data-i18n=\"siteOnePagePage.ctaTitle\">Pronto para lançar seu site One Page?</h2>\n        <p style=\"max-width: 600px; margin: 1rem auto 2rem; color: var(--color-text-muted);\">\n          Fale conosco hoje mesmo e coloque sua empresa na web com uma estrutura profissional e objetiva.\n        </p>\n        <a href=\"#\" class=\"btn btn-primary\" data-whatsapp-key=\"serviceOnePage\" data-track=\"whatsapp_click\" data-cta-position=\"onepage_footer_cta\">\n          Quero meu site One Page\n          <svg class=\"btn-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n        </a>\n      </div>\n    </section>"
